//! Rtnetlink helpers - native netlink operations for IP addresses and routes

use anyhow::{Context, Result};
use futures::TryStreamExt;
use netlink_packet_route::address::AddressAttribute;
use netlink_packet_route::link::LinkAttribute;
use rtnetlink::{new_connection, IpVersion};
use serde::{Deserialize, Serialize};
use std::net::Ipv4Addr;

/// Network interface information
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NetworkInterface {
    pub name: String,
    pub index: u32,
    pub mac_address: Option<String>,
    pub mtu: Option<u32>,
    pub flags: Vec<String>,
    pub state: String,
    pub kind: Option<String>,
    pub addresses: Vec<InterfaceAddress>,
}

/// IP address on an interface
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct InterfaceAddress {
    pub address: String,
    pub prefix_len: u8,
    pub family: String,
}

/// List all network interfaces with their details
pub async fn list_interfaces() -> Result<Vec<NetworkInterface>> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    let mut interfaces = Vec::new();
    let mut links = handle.link().get().execute();

    while let Some(link) = links.try_next().await? {
        let index = link.header.index;
        let mut name = String::new();
        let mut mac_address = None;
        let mut mtu = None;
        let mut kind = None;

        // Extract attributes
        for attr in &link.attributes {
            match attr {
                LinkAttribute::IfName(n) => name = n.clone(),
                LinkAttribute::Address(addr) => {
                    mac_address = Some(
                        addr.iter()
                            .map(|b| format!("{:02x}", b))
                            .collect::<Vec<_>>()
                            .join(":"),
                    );
                }
                LinkAttribute::Mtu(m) => mtu = Some(*m),
                LinkAttribute::LinkInfo(infos) => {
                    for info in infos {
                        if let netlink_packet_route::link::LinkInfo::Kind(k) = info {
                            kind = Some(format!("{:?}", k));
                        }
                    }
                }
                _ => {}
            }
        }

        // Determine state from flags
        let flags_val = &link.header.flags;
        let flags: Vec<String> = flags_val.iter().map(|f| format!("{:?}", f)).collect();
        let is_up = flags_val
            .iter()
            .any(|f| matches!(f, netlink_packet_route::link::LinkFlag::Up));
        let state = if is_up {
            "up".to_string()
        } else {
            "down".to_string()
        };

        // Get addresses for this interface
        let addresses = match get_interface_addresses(&handle, index).await {
            Ok(addrs) => addrs,
            Err(e) => {
                log::warn!("Failed to get addresses for interface {}: {}", name, e);
                Vec::new()
            }
        };

        interfaces.push(NetworkInterface {
            name,
            index,
            mac_address,
            mtu,
            flags,
            state,
            kind,
            addresses,
        });
    }

    Ok(interfaces)
}

/// Get addresses for a specific interface
async fn get_interface_addresses(
    handle: &rtnetlink::Handle,
    ifindex: u32,
) -> Result<Vec<InterfaceAddress>> {
    let mut addresses = Vec::new();
    let mut addr_stream = handle
        .address()
        .get()
        .set_link_index_filter(ifindex)
        .execute();

    while let Some(addr_msg) = addr_stream.try_next().await? {
        let family = match addr_msg.header.family {
            netlink_packet_route::AddressFamily::Inet => "inet".to_string(),
            netlink_packet_route::AddressFamily::Inet6 => "inet6".to_string(),
            f => format!("{:?}", f),
        };

        for attr in &addr_msg.attributes {
            if let AddressAttribute::Address(addr) = attr {
                let addr_str = addr.to_string();

                addresses.push(InterfaceAddress {
                    address: addr_str,
                    prefix_len: addr_msg.header.prefix_len,
                    family: family.clone(),
                });
            }
        }
    }

    Ok(addresses)
}

/// Get default route information
pub async fn get_default_route() -> Result<Option<serde_json::Value>> {
    use netlink_packet_route::route::RouteAttribute;

    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    let mut routes = handle.route().get(IpVersion::V4).execute();

    while let Some(route) = routes.try_next().await? {
        // Check if this is a default route (destination 0.0.0.0/0)
        if route.header.destination_prefix_length == 0 {
            let mut gateway = None;
            let mut oif_index = None;

            for attr in &route.attributes {
                match attr {
                    RouteAttribute::Gateway(gw) => {
                        gateway = Some(format!("{:?}", gw));
                    }
                    RouteAttribute::Oif(idx) => {
                        oif_index = Some(idx);
                    }
                    _ => {}
                }
            }

            // Try to get interface name for the output interface
            let mut oif_name = None;
            if let Some(idx) = oif_index {
                let mut links = handle.link().get().match_index(*idx).execute();
                if let Some(link) = links.try_next().await? {
                    for attr in &link.attributes {
                        if let LinkAttribute::IfName(name) = attr {
                            oif_name = Some(name.clone());
                            break;
                        }
                    }
                }
            }

            return Ok(Some(serde_json::json!({
                "gateway": gateway,
                "interface_index": oif_index,
                "interface_name": oif_name,
                "destination": "0.0.0.0/0",
            })));
        }
    }

    Ok(None)
}

/// Add IPv4 address to interface
pub async fn add_ipv4_address(ifname: &str, ip: &str, prefix: u8) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    // Find interface by name
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", ifname))?;

    let ifindex = link.header.index;

    // Parse IP address
    let addr: Ipv4Addr = ip.parse().context("Invalid IPv4 address")?;

    // Add address to interface
    handle
        .address()
        .add(ifindex, addr.into(), prefix)
        .execute()
        .await
        .context("Failed to add IP address")?;

    Ok(())
}

/// Delete IPv4 address from interface
#[allow(dead_code)]
pub async fn del_ipv4_address(ifname: &str, ip: &str, prefix: u8) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    // Find interface by name
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", ifname))?;

    let ifindex = link.header.index;

    // Parse IP address
    let addr: Ipv4Addr = ip.parse().context("Invalid IPv4 address")?;

    // Get addresses filtered by interface, prefix, and address
    let mut addresses = handle
        .address()
        .get()
        .set_link_index_filter(ifindex)
        .set_prefix_length_filter(prefix)
        .set_address_filter(std::net::IpAddr::V4(addr))
        .execute();

    if let Some(addr_msg) = addresses.try_next().await? {
        handle.address().del(addr_msg).execute().await?;
    }

    Ok(())
}

/// Flush all addresses from interface
#[allow(dead_code)]
pub async fn flush_addresses(ifname: &str) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    // Find interface by name
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", ifname))?;

    let ifindex = link.header.index;

    // Get all addresses on this interface
    let mut addresses = handle
        .address()
        .get()
        .set_link_index_filter(ifindex)
        .execute();

    while let Some(addr) = addresses.try_next().await? {
        // Delete this address
        if let Err(e) = handle.address().del(addr).execute().await {
            log::warn!("Failed to delete address: {}", e);
        }
    }

    Ok(())
}

/// Set link up
pub async fn link_up(ifname: &str) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    // Find interface by name
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", ifname))?;

    let ifindex = link.header.index;

    // Set link up
    handle
        .link()
        .set(ifindex)
        .up()
        .execute()
        .await
        .context("Failed to bring link up")?;

    Ok(())
}

/// Set link down
#[allow(dead_code)]
pub async fn link_down(ifname: &str) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    // Find interface by name
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", ifname))?;

    let ifindex = link.header.index;

    // Set link down
    handle
        .link()
        .set(ifindex)
        .down()
        .execute()
        .await
        .context("Failed to bring link down")?;

    Ok(())
}

/// Add default route
pub async fn add_default_route(ifname: &str, gateway: &str) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    // Find interface by name
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", ifname))?;

    let ifindex = link.header.index;

    // Parse gateway address
    let gw: Ipv4Addr = gateway.parse().context("Invalid gateway address")?;

    // Add default route
    handle
        .route()
        .add()
        .v4()
        .destination_prefix(Ipv4Addr::new(0, 0, 0, 0), 0)
        .gateway(gw)
        .output_interface(ifindex)
        .execute()
        .await
        .context("Failed to add default route")?;

    Ok(())
}

/// Add default route with `onlink` flag via native netlink.
///
/// Required when the output interface is an OVS internal port: the kernel
/// cannot verify gateway reachability until OVS is forwarding, so we must
/// bypass nexthop validation.  We build the `RTM_NEWROUTE` message manually
/// using `netlink-packet-route` so that the `RTNH_F_ONLINK` (0x04) flag is
/// set in the nexthop attribute — the high-level `rtnetlink` crate does not
/// expose this flag through its typed builder.
pub async fn add_default_route_onlink(ifname: &str, gateway: &str) -> Result<()> {
    use netlink_packet_core::{
        NetlinkHeader, NetlinkMessage, NetlinkPayload, NLM_F_ACK, NLM_F_CREATE, NLM_F_REPLACE,
        NLM_F_REQUEST,
    };
    use netlink_packet_route::route::{
        RouteAddress, RouteAttribute, RouteHeader, RouteMessage, RouteNextHop, RouteNextHopFlag,
        RouteProtocol, RouteScope, RouteType,
    };
    use netlink_packet_route::RouteNetlinkMessage;
    use netlink_sys::{protocols::NETLINK_ROUTE, Socket};

    // Resolve interface index
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", ifname))?;
    let ifindex = link.header.index;

    let gw: Ipv4Addr = gateway.parse().context("Invalid gateway address")?;

    // Build the route message manually.
    let mut route_msg = RouteMessage::default();
    route_msg.header.address_family = netlink_packet_route::AddressFamily::Inet;
    route_msg.header.destination_prefix_length = 0;
    route_msg.header.source_prefix_length = 0;
    route_msg.header.tos = 0;
    route_msg.header.table = RouteHeader::RT_TABLE_MAIN;
    route_msg.header.protocol = RouteProtocol::Static;
    route_msg.header.scope = RouteScope::Link; // RT_SCOPE_LINK — onlink semantics
    route_msg.header.kind = RouteType::Unicast;
    route_msg.header.flags = Vec::new();

    // Destination prefix (0.0.0.0/0)
    route_msg
        .attributes
        .push(RouteAttribute::Destination(RouteAddress::Inet(
            Ipv4Addr::new(0, 0, 0, 0),
        )));

    // Encode the single nexthop with RTNH_F_ONLINK via RTA_MULTIPATH.
    // iproute2 uses RTA_NEXTHOP (type 3) for single-path routes with flags,
    // but netlink-packet-route 0.19 does not expose a typed RTA_NEXTHOP
    // variant.  The kernel accepts RTA_MULTIPATH with one element and
    // treats it identically for non-ECMP routes.
    let mut nh = RouteNextHop::default();
    nh.flags = vec![RouteNextHopFlag::Onlink];
    nh.hops = 0;
    nh.interface_index = ifindex;
    nh.attributes = vec![RouteAttribute::Gateway(RouteAddress::Inet(gw))];
    route_msg
        .attributes
        .push(RouteAttribute::MultiPath(vec![nh]));

    // Build netlink envelope
    let mut header = NetlinkHeader::default();
    header.sequence_number = 1;
    header.flags = NLM_F_REQUEST | NLM_F_ACK | NLM_F_CREATE | NLM_F_REPLACE;
    let mut nl_msg = NetlinkMessage::new(
        header,
        NetlinkPayload::from(RouteNetlinkMessage::NewRoute(route_msg)),
    );
    nl_msg.finalize();

    let socket = Socket::new(NETLINK_ROUTE).context("open NETLINK_ROUTE socket")?;
    let mut buf = vec![0u8; nl_msg.buffer_len()];
    nl_msg.serialize(&mut buf);
    socket.send(&buf, 0).context("send RTM_NEWROUTE")?;

    // Wait for ACK (or error)
    let mut recv_buf = vec![0u8; 4096];
    let len = socket.recv(&mut recv_buf, 0).context("recv netlink ACK")?;
    recv_buf.truncate(len);

    let ack_msg: NetlinkMessage<RouteNetlinkMessage> =
        NetlinkMessage::deserialize(&recv_buf).context("deserialize netlink ACK")?;
    if let NetlinkPayload::Error(e) = ack_msg.payload {
        if e.code.is_some() {
            anyhow::bail!(
                "netlink RTM_NEWROUTE failed for default via {} dev {} onlink: {:?}",
                gateway,
                ifname,
                e,
            );
        }
    }

    Ok(())
}

/// Set MAC address on interface
pub async fn set_mac_address(ifname: &str, mac: &str) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    // Find interface by name
    let mut links = handle.link().get().match_name(ifname.to_string()).execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", ifname))?;

    let ifindex = link.header.index;

    // Parse MAC address "aa:bb:cc:dd:ee:ff" -> [u8; 6]
    let mac_bytes: Vec<u8> = mac
        .split(':')
        .map(|byte| u8::from_str_radix(byte, 16).context("Invalid MAC address byte"))
        .collect::<Result<Vec<u8>>>()?;

    if mac_bytes.len() != 6 {
        return Err(anyhow::anyhow!(
            "Invalid MAC address '{}': expected 6 octets",
            mac
        ));
    }

    // Set MAC address
    handle
        .link()
        .set(ifindex)
        .address(mac_bytes)
        .execute()
        .await
        .context("Failed to set MAC address")?;

    Ok(())
}

/// Delete default route
pub async fn del_default_route() -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    // Get all routes
    let mut routes = handle.route().get(IpVersion::V4).execute();

    while let Some(route) = routes.try_next().await? {
        // Check if this is a default route (destination 0.0.0.0/0)
        if route.header.destination_prefix_length == 0 {
            // Delete this route
            if let Err(e) = handle.route().del(route).execute().await {
                log::warn!("Failed to delete default route: {}", e);
            }
        }
    }

    Ok(())
}

/// List IPv4 routes for a given interface (by name)
pub async fn list_routes_for_interface(_ifname: &str) -> Result<Vec<serde_json::Value>> {
    // Minimal, compile-safe stub; route filtering can be added later.
    Ok(Vec::new())
}

/// List all veth interfaces (simplified implementation)
pub async fn list_veth_interfaces() -> Result<Vec<String>> {
    // For now, return empty list - this would need more complex rtnetlink code
    // to properly enumerate all interfaces and check their types
    // The LXC plugin will fall back to other methods if this returns empty
    Ok(Vec::new())
}

/// Rename network interface
pub async fn link_set_name(old_name: &str, new_name: &str) -> Result<()> {
    let (connection, handle, _) = new_connection()?;
    tokio::spawn(connection);

    // Find interface by current name
    let mut links = handle
        .link()
        .get()
        .match_name(old_name.to_string())
        .execute();
    let link = links
        .try_next()
        .await?
        .context(format!("Interface '{}' not found", old_name))?;

    let ifindex = link.header.index;

    // Set new name
    handle
        .link()
        .set(ifindex)
        .name(new_name.to_string())
        .execute()
        .await
        .context(format!("Failed to rename {} to {}", old_name, new_name))?;

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    // Basic smoke test to ensure rtnetlink connection and route listing works.
    // Uses the loopback interface which always exists.
    #[tokio::test(flavor = "current_thread")]
    async fn test_list_routes_for_loopback() {
        let res = list_routes_for_interface("lo").await;
        assert!(
            res.is_ok(),
            "expected Ok from list_routes_for_interface: {:?}",
            res
        );
        let routes = res.unwrap();
        // No strict expectation on content; presence/empty is both fine.
        println!("routes on lo: {:?}", routes);
    }
}
//! Rtnetlink state plugin - manages kernel-level network interface state
//!
//! Handles: IP addresses, link state (up/down), MAC addresses, default routes
//! Uses native rtnetlink (netlink) protocol — no CLI wrappers.
//! Depends on: net, ovsdb_bridge (interfaces must exist before configuring)

use anyhow::Result;
use async_trait::async_trait;
use op_state::{
    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
};
use op_state_store::{FieldSchema, FieldType, PluginSchema};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use simd_json::prelude::*;
use simd_json::{json, OwnedValue as Value};
use std::collections::HashMap;

/// Rtnetlink interface configuration
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RtnetlinkInterfaceConfig {
    /// Interface name (e.g., "ens3", "ovsbr0-int")
    pub name: String,

    /// IPv4/IPv6 addresses to assign
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub addresses: Option<Vec<AddressEntry>>,

    /// MAC address to set (e.g., "fa:16:3e:f1:71:d2")
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mac_address: Option<String>,

    /// MTU
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mtu: Option<u32>,

    /// Desired link state: "up" or "down"
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub state: Option<String>,

    /// Default gateway (only one interface should set this)
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub default_gateway: Option<String>,
}

/// IP address entry
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct AddressEntry {
    pub ip: String,
    pub prefix: u8,
}

/// Rtnetlink state — list of managed interfaces
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RtnetlinkState {
    pub interfaces: Vec<RtnetlinkInterfaceConfig>,
}

pub struct RtnetlinkPlugin;

impl RtnetlinkPlugin {
    pub fn new() -> Self {
        Self
    }
}

impl Default for RtnetlinkPlugin {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl StatePlugin for RtnetlinkPlugin {
    fn name(&self) -> &str {
        "rtnetlink"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<op_state_store::PluginSchema> {
        Some(rtnetlink_schema())
    }

    fn is_available(&self) -> bool {
        // rtnetlink is always available — it's the kernel
        true
    }

    fn unavailable_reason(&self) -> String {
        "rtnetlink is always available".to_string()
    }

    async fn calculate_diff(&self, current: &Value, desired: &Value) -> Result<StateDiff> {
        let current_state: RtnetlinkState = simd_json::serde::from_owned_value(current.clone())
            .unwrap_or(RtnetlinkState { interfaces: vec![] });
        let desired_state: RtnetlinkState = simd_json::serde::from_owned_value(desired.clone())
            .unwrap_or(RtnetlinkState { interfaces: vec![] });

        let mut actions = Vec::new();

        let current_map: HashMap<&str, &RtnetlinkInterfaceConfig> = current_state
            .interfaces
            .iter()
            .map(|i| (i.name.as_str(), i))
            .collect();

        for desired_iface in &desired_state.interfaces {
            if let Some(current_iface) = current_map.get(desired_iface.name.as_str()) {
                // Check if any property differs
                let needs_update = desired_iface.state != current_iface.state
                    || desired_iface.mac_address != current_iface.mac_address
                    || desired_iface.addresses != current_iface.addresses
                    || desired_iface.default_gateway.is_some();

                if needs_update {
                    actions.push(StateAction::Modify {
                        resource: desired_iface.name.clone(),
                        changes: simd_json::serde::to_owned_value(desired_iface)?,
                    });
                }
            } else {
                // Interface not found in kernel — can only configure if it exists
                log::warn!(
                    "rtnetlink: desired interface '{}' not found in kernel",
                    desired_iface.name
                );
            }
        }

        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions,
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: format!("{:x}", md5::compute(simd_json::to_string(current)?)),
                desired_hash: format!("{:x}", md5::compute(simd_json::to_string(desired)?)),
            },
        })
    }

    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
        let mut changes_applied = Vec::new();
        let mut errors = Vec::new();

        for action in &diff.actions {
            if let StateAction::Modify { resource, changes } = action {
                let config: RtnetlinkInterfaceConfig =
                    simd_json::serde::from_owned_value(changes.clone())?;

                // Set MAC address
                if let Some(ref mac) = config.mac_address {
                    match op_network::rtnetlink::set_mac_address(resource, mac).await {
                        Ok(_) => changes_applied
                            .push(format!("Set MAC {} on {} via rtnetlink", mac, resource)),
                        Err(e) => errors.push(format!("Failed to set MAC on {}: {}", resource, e)),
                    }
                }

                // Add IP addresses
                if let Some(ref addresses) = config.addresses {
                    for addr in addresses {
                        match op_network::rtnetlink::add_ipv4_address(
                            resource,
                            &addr.ip,
                            addr.prefix,
                        )
                        .await
                        {
                            Ok(_) => changes_applied.push(format!(
                                "Added {}/{} to {} via rtnetlink",
                                addr.ip, addr.prefix, resource
                            )),
                            Err(e) => {
                                // EEXIST is not an error — address already assigned
                                let msg = e.to_string();
                                if msg.contains("exist") {
                                    log::info!(
                                        "Address {}/{} already on {} (ok)",
                                        addr.ip,
                                        addr.prefix,
                                        resource
                                    );
                                } else {
                                    errors.push(format!(
                                        "Failed to add {}/{} to {}: {}",
                                        addr.ip, addr.prefix, resource, e
                                    ));
                                }
                            }
                        }
                    }
                }

                // Set link state
                if let Some(ref state) = config.state {
                    let result = if state == "up" {
                        op_network::rtnetlink::link_up(resource).await
                    } else {
                        op_network::rtnetlink::link_down(resource).await
                    };
                    match result {
                        Ok(_) => changes_applied
                            .push(format!("Set {} {} via rtnetlink", resource, state)),
                        Err(e) => {
                            errors.push(format!("Failed to set {} {}: {}", resource, state, e))
                        }
                    }
                }

                // Set default gateway
                if let Some(ref gateway) = config.default_gateway {
                    // Delete existing default route first
                    let _ = op_network::rtnetlink::del_default_route().await;
                    match op_network::rtnetlink::add_default_route(resource, gateway).await {
                        Ok(_) => changes_applied.push(format!(
                            "Set default route via {} on {} via rtnetlink",
                            gateway, resource
                        )),
                        Err(e) => errors.push(format!(
                            "Failed to set default route via {}: {}",
                            gateway, e
                        )),
                    }
                }
            }
        }

        Ok(ApplyResult {
            success: errors.is_empty(),
            changes_applied,
            errors,
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        let state = simd_json::json!(null);
        Ok(Checkpoint {
            id: format!("rtnetlink-{}", chrono::Utc::now().timestamp()),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: state,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, checkpoint: &Checkpoint) -> Result<()> {
        let old_state: RtnetlinkState =
            simd_json::serde::from_owned_value(checkpoint.state_snapshot.clone())?;

        // Re-apply old state
        let current = simd_json::json!(null);
        let diff = self
            .calculate_diff(&current, &simd_json::serde::to_owned_value(&old_state)?)
            .await?;
        self.apply_state(&diff).await?;

        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: true,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

