#!/bin/sh
set -eu

exec 2>&1

SOCKET=${QDRANT_GRPC_SOCKET:-/var/lib/opdbus-runtime/qdrant/qdrant-grpc.sock}
PORT=${QDRANT_GRPC_PORT:-6334}

while [ ! -S "$SOCKET" ]; do
    sleep 1
done

exec socat \
    "TCP-LISTEN:${PORT},bind=127.0.0.1,reuseaddr,fork" \
    "UNIX-CONNECT:${SOCKET}"

                                                    None,
                                                    simd_val,
                                                    vec![
                                                        "ovsdb".to_string(),
                                                        "network".to_string(),
                                                    ],
                                                    "ovsdb-monitor".to_string(),
                                                    None,
                                                    ChangeSource::DBus,
                                                )
                                                .await;
                                        }
                                    }
                                }
                            }
                        }
                        Err(tokio::sync::broadcast::error::RecvError::Lagged(n)) => {
                            tracing::warn!("OVSDB subscription lagged by {} events", n);
                            continue;
                        }
                        Err(tokio::sync::broadcast::error::RecvError::Closed) => break,
                    }
                }
            }
        });

        Ok(())
    }

    /// Unified mutation entry point. Writes to authoritative RCP stores and
    /// triggers the event recording/broadcast pipeline.
    #[allow(clippy::too_many_arguments)]
    pub async fn mutate(
        &self,
