/// OpenFlow protocol versions.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
#[repr(u8)]
pub enum Version {
    /// OpenFlow 1.0
    Of10 = 0x01,
    /// OpenFlow 1.1
    Of11 = 0x02,
    /// OpenFlow 1.2
    Of12 = 0x03,
    /// OpenFlow 1.3
    Of13 = 0x04,
    /// OpenFlow 1.4
    Of14 = 0x05,
    /// OpenFlow 1.5
    Of15 = 0x06,
}

impl Version {
    /// Get the wire format version number.
    pub fn wire_version(self) -> u8 {
        self as u8
    }
    if state & ct_state::REL != 0 { parts.push("+rel"); }
    if state & ct_state::RPL != 0 { parts.push("+rpl"); }
    if state & ct_state::INV != 0 { parts.push("+inv"); }
    if state & ct_state::SNAT != 0 { parts.push("+snat"); }
    if state & ct_state::DNAT != 0 { parts.push("+dnat"); }
    if parts.is_empty() {
        format!("0x{state:x}")
    } else {
        parts.join("")
    }
}

