            flags: 0,
        };
        let bytes = header.encode();
        assert_eq!(bytes.len(), 8);
        assert_eq!(bytes[0..2], [0x00, 0x01]); // Flow = 1
        assert_eq!(bytes[2..4], [0x00, 0x00]); // flags = 0
        assert_eq!(bytes[4..8], [0x00, 0x00, 0x00, 0x00]); // padding
    }

