//! OCI attachment state for Incus-managed containers that need host-side
//! bootstrap (loopback, OVS internal port, namespace address, and routes).
//!
//! Lifecycle remains owned by Incus/runit. This plugin owns only the declared
//! attachment and resolves the running instance PID immediately before every
//! namespace transaction.

use anyhow::{Context, Result};
use op_state::{
    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
};
use op_state_store::{FieldSchema, FieldType, PluginSchema};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use simd_json::json;
use simd_json::OwnedValue as Value;
use std::collections::HashMap;

// ── Typed state ──────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq)]
pub struct OciState {
    #[serde(default)]
    pub containers: Vec<OciContainerConfig>,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq)]
pub struct OciContainerConfig {
    pub name: String,
    #[serde(default)]
    pub image: String,
    #[serde(default)]
    pub loopback_required: bool,
    #[serde(default)]
    pub entrypoint_override: Option<String>,
    #[serde(default)]
    pub privileged: bool,
    #[serde(default)]
    pub env: HashMap<String, String>,
    #[serde(default)]
    pub sockets: Vec<serde_json::Value>,
    #[serde(default)]
    pub volumes: Vec<serde_json::Value>,
    #[serde(default)]
    pub port_attach: Option<PortAttachConfig>,
    #[serde(default)]
    pub grpc_adapter: Option<GrpcAdapterConfig>,
    #[serde(default)]
    pub supervision: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, JsonSchema)]
pub struct PortAttachConfig {
    pub bridge: String,
    pub port_name: String,
    #[serde(default)]
    pub ip_addrs: Vec<String>,
    pub gateway: String,
    #[serde(default)]
    pub routes: Vec<PortRouteConfig>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, JsonSchema)]
pub struct PortRouteConfig {
    pub destination: String,
    #[serde(default)]
    pub gateway: Option<String>,
    #[serde(default)]
    pub table: Option<u32>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, JsonSchema)]
pub struct GrpcAdapterConfig {
    pub binary: String,
    pub socket: String,
    pub host_endpoint: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct AttachmentActionConfig {
    container_name: String,
    loopback_required: bool,
    port_attach: PortAttachConfig,
}

// ── Schema definition — THE PLUGIN IS THE SCHEMA ───────────────────────────

fn field(
    field_type: FieldType,
    required: bool,
    description: &str,
    default: Option<Value>,
    example: Option<Value>,
) -> FieldSchema {
    FieldSchema {
        field_type,
        required,
        description: description.to_string(),
        default,
        example,
        constraints: Vec::new(),
        read_only: false,
        read_only_when: None,
    }
}

fn route_fields() -> HashMap<String, FieldSchema> {
    HashMap::from([
        (
            "destination".to_string(),
            field(
                FieldType::String,
                true,
                "IPv4 destination in CIDR notation",
                None,
                Some(json!("10.10.0.0/16")),
            ),
        ),
        (
            "gateway".to_string(),
            field(
                FieldType::String,
                false,
                "Optional IPv4 next hop",
                None,
                Some(json!("10.200.1.2")),
            ),
        ),
        (
            "table".to_string(),
            field(
                FieldType::Integer,
                false,
                "Optional route table number",
                None,
                Some(json!(254)),
            ),
        ),
    ])
}

fn port_attach_fields() -> HashMap<String, FieldSchema> {
    HashMap::from([
        (
            "bridge".to_string(),
            field(
                FieldType::String,
                true,
                "Existing OVS bridge",
                None,
                Some(json!("ovsbr0")),
            ),
        ),
        (
            "port_name".to_string(),
            field(
                FieldType::String,
                true,
                "OVS internal port name",
                None,
                Some(json!("netmk")),
            ),
        ),
        (
            "ip_addrs".to_string(),
            field(
                FieldType::Array(Box::new(FieldType::String)),
                false,
                "IPv4 addresses assigned inside the container namespace",
                Some(json!([])),
                Some(json!(["10.200.1.1/30"])),
            ),
        ),
        (
            "gateway".to_string(),
            field(
                FieldType::String,
                true,
                "Default IPv4 gateway inside the namespace",
                None,
                Some(json!("10.200.1.2")),
            ),
        ),
        (
            "routes".to_string(),
            field(
                FieldType::Array(Box::new(FieldType::Object(route_fields()))),
                false,
                "Additional namespace-local IPv4 routes",
                Some(json!([])),
                Some(json!([])),
            ),
        ),
    ])
}

fn grpc_adapter_fields() -> HashMap<String, FieldSchema> {
    HashMap::from([
        (
            "binary".to_string(),
            field(
                FieldType::String,
                true,
                "Adapter binary supervised inside the container",
                None,
                Some(json!("op-grpc-adapters")),
            ),
        ),
        (
            "socket".to_string(),
            field(
                FieldType::String,
                true,
                "Bind-mounted adapter Unix socket",
                None,
                Some(json!(
                    "/var/lib/opdbus-runtime/netmaker/op-grpc-adapters.sock"
                )),
            ),
        ),
        (
            "host_endpoint".to_string(),
            field(
                FieldType::String,
                true,
                "Dedicated host loopback endpoint",
                None,
                Some(json!("http://127.0.0.1:50061")),
            ),
        ),
    ])
}

fn oci_container_fields() -> HashMap<String, FieldSchema> {
    let mut fields = HashMap::new();
    fields.insert(
        "name".to_string(),
        FieldSchema {
            read_only: true,
            ..field(
                FieldType::String,
                true,
                "Incus instance name",
                None,
                Some(json!("netmaker")),
            )
        },
    );
    fields.insert(
        "image".to_string(),
        field(
            FieldType::String,
            false,
            "OCI image reference",
            None,
            Some(json!("docker:gravitl/netmaker:v1.5.1")),
        ),
    );
    fields.insert(
        "loopback_required".to_string(),
        field(
            FieldType::Boolean,
            false,
            "Bring loopback UP before attached services start",
            Some(json!(false)),
            Some(json!(true)),
        ),
    );
    fields.insert(
        "entrypoint_override".to_string(),
        field(
            FieldType::String,
            false,
            "Optional OCI entrypoint wrapper",
            None,
            None,
        ),
    );
    fields.insert(
        "privileged".to_string(),
        field(
            FieldType::Boolean,
            false,
            "Whether the container runs privileged",
            Some(json!(false)),
            Some(json!(true)),
        ),
    );
    fields.insert(
        "env".to_string(),
        field(
            FieldType::Any,
            false,
            "Container environment variables",
            Some(json!({})),
            None,
        ),
    );
    fields.insert(
        "sockets".to_string(),
        field(
            FieldType::Array(Box::new(FieldType::Any)),
            false,
            "Incus proxy socket devices",
            Some(json!([])),
            None,
        ),
    );
    fields.insert(
        "volumes".to_string(),
        field(
            FieldType::Array(Box::new(FieldType::Any)),
            false,
            "Incus volume devices",
            Some(json!([])),
            None,
        ),
    );
    fields.insert(
        "port_attach".to_string(),
        field(
            FieldType::Object(port_attach_fields()),
            false,
            "Typed OVS internal-port attachment reconciled into the current container netns",
            None,
            Some(json!({
                "bridge": "ovsbr0",
                "port_name": "netmk",
                "ip_addrs": ["10.200.1.1/30"],
                "gateway": "10.200.1.2",
                "routes": []
            })),
        ),
    );
    fields.insert(
        "grpc_adapter".to_string(),
        field(
            FieldType::Object(grpc_adapter_fields()),
            false,
            "Dedicated adapter UDS and host endpoint",
            None,
            None,
        ),
    );
    fields.insert(
        "supervision".to_string(),
        field(
            FieldType::String,
            false,
            "Container feature supervisor (runit only)",
            Some(json!("runit")),
            Some(json!("runit")),
        ),
    );
    fields
}

/// Input struct for pulling an OCI image.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
