pub(crate) fn oci_schema() -> PluginSchema {
    PluginSchema::builder("oci")
        .category("container")
        .version("1.0.0")
        .description("OCI lifecycle declarations and native OVS/netns port attachment")
        .dependency("incus")
        .dependency("rovs_commands")
        .dependency("rtnetlink")
        .array_field(
            "containers",
            FieldType::Object(oci_container_fields()),
            true,
            "Declared OCI containers with lifecycle and attachment config",
        )
        .example(json!({
            "containers": [{
                "name": "netmaker",
                "image": "docker:gravitl/netmaker:v1.5.1",
                "loopback_required": true,
                "port_attach": {
                    "bridge": "ovsbr0",
                    "port_name": "netmk",
                    "ip_addrs": ["10.200.1.1/30"],
                    "gateway": "10.200.1.2",
                    "routes": []
                },
                "grpc_adapter": {
                    "binary": "op-grpc-adapters",
                    "socket": "/var/lib/opdbus-runtime/netmaker/op-grpc-adapters.sock",
                    "host_endpoint": "http://127.0.0.1:50061"
                },
                "supervision": "runit"
            }]
        }))
        .method(super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<PullImageInput, super::plugin_scaffold_helpers::AckOutput>(
            "pull_image", op_state_store::SideEffect::Mutation, false,
            "cap.container.oci.image.pull@v1", "mut.container.oci.image.pull@v1"))
        .method(super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<RunContainerInput, super::plugin_scaffold_helpers::AckOutput>(
            "run_container", op_state_store::SideEffect::Mutation, false,
            "cap.container.oci.run@v1", "mut.container.oci.run@v1"))
        .method(super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<CreateContainerInput, super::plugin_scaffold_helpers::AckOutput>(
            "create", op_state_store::SideEffect::Mutation, false,
            "cap.container.oci.create@v1", "mut.container.oci.create@v1"))
        .method(super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<StartContainerInput, super::plugin_scaffold_helpers::AckOutput>(
            "start", op_state_store::SideEffect::Mutation, false,
            "cap.container.oci.start@v1", "mut.container.oci.start@v1"))
        .method(super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<KillContainerInput, super::plugin_scaffold_helpers::AckOutput>(
            "kill", op_state_store::SideEffect::Mutation, false,
            "cap.container.oci.kill@v1", "mut.container.oci.kill@v1"))
        .method(super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<DeleteContainerInput, super::plugin_scaffold_helpers::AckOutput>(
            "delete", op_state_store::SideEffect::Mutation, false,
            "cap.container.oci.delete@v1", "mut.container.oci.delete@v1"))
        .method(super::plugin_scaffold_helpers::method_decl_from_schemars_with_output::<GetContainerStateInput, super::plugin_scaffold_helpers::AckOutput>(
            "state", op_state_store::SideEffect::Read, true,
            "cap.container.oci.state.get@v1", "obs.container.oci.state.get@v1"))
        .build()
}

