#[cfg(test)]
mod tests {
    use super::*;

    fn netmaker_state() -> Value {
        json!({
            "containers": [{
                "name": "netmaker",
                "loopback_required": true,
                "port_attach": {
                    "bridge": "ovsbr0",
                    "port_name": "netmk",
