    let endpoint =
        std::env::var("VPN_ENDPOINT").unwrap_or_else(|_| "148.113.204.83:51820".to_string());

    Json(VpnConfig {
        server_public_key,
        endpoint,
        network: "10.100.0.0/24".to_string(),
        dns: "1.1.1.1".to_string(),
    })
