    }

    /// Set the hard timeout.
    pub fn hard_timeout(mut self, timeout: u16) -> Self {
        self.hard_timeout = timeout;
        self
    }

    /// Encode the FlowMod fixed fields (40 bytes).
    ///
    /// ```text
    /// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    /// |                            cookie                             |
    /// |                                                               |
    /// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    /// |                         cookie_mask                           |
    /// |                                                               |
    /// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    /// |   table_id  |    command    |         idle_timeout            |
    /// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    /// |         hard_timeout        |           priority              |
    /// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    /// |                          buffer_id                            |
    /// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    /// |                          out_port                             |
    /// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    /// |                          out_group                            |
    /// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    /// |            flags            |           pad (zeros)           |
    /// +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+
    /// ```
    fn encode_fixed(&self) -> [u8; 40] {
        let mut buf = [0u8; 40];

        // cookie (8 bytes)
        buf[0..8].copy_from_slice(&self.cookie.to_be_bytes());

        // cookie_mask (8 bytes)
        buf[8..16].copy_from_slice(&self.cookie_mask.to_be_bytes());

        // table_id (1 byte)
        buf[16] = self.table_id;

        // command (1 byte)
        buf[17] = self.command as u8;

        // idle_timeout (2 bytes)
        buf[18..20].copy_from_slice(&self.idle_timeout.to_be_bytes());

        // hard_timeout (2 bytes)
        buf[20..22].copy_from_slice(&self.hard_timeout.to_be_bytes());

        // priority (2 bytes)
        buf[22..24].copy_from_slice(&self.priority.to_be_bytes());

        // buffer_id (4 bytes)
        let buffer_id = self.buffer_id.unwrap_or(OFP_NO_BUFFER);
        buf[24..28].copy_from_slice(&buffer_id.to_be_bytes());

        // out_port (4 bytes)
        let out_port = self.out_port.unwrap_or(OFPP_ANY);
        buf[28..32].copy_from_slice(&out_port.to_be_bytes());

        // out_group (4 bytes)
        let out_group = self.out_group.unwrap_or(OFPG_ANY);
        buf[32..36].copy_from_slice(&out_group.to_be_bytes());

        // flags (2 bytes)
        buf[36..38].copy_from_slice(&self.flags.to_wire().to_be_bytes());

        // pad (2 bytes) - already zeroed

        buf
    }

    /// Encode the complete FlowMod body (without OF header).
    ///
    /// Returns: fixed fields (40) + match (variable) + instructions (variable)
    pub fn encode(&self) -> Vec<u8> {
        let fixed = self.encode_fixed();
        let match_bytes = self.match_fields.encode();

        // Build instructions: use explicit instructions if set, otherwise wrap actions
        let instruction_bytes = if self.instructions.is_empty() && !self.actions.is_empty() {
            // Wrap actions in ApplyActions instruction
            let inst = Instruction::ApplyActions(self.actions.clone());
            inst.encode()
        } else {
            self.instructions.encode()
        };
        flags |= match tok {
            "fin" => 0x001,
            "syn" => 0x002,
            "rst" => 0x004,
            "psh" => 0x008,
            "ack" => 0x010,
            "urg" => 0x020,
            "ece" => 0x040,
            "cwr" => 0x080,
            "ns" => 0x100,
            other => bail!("unknown tcp_flags token '+{}' in '{}'", other, s),
        };
    }
    Ok(flags)
}

/// Parse OVS `ct_state` syntax (e.g. `+est+trk`, `+inv+trk`) into (value, mask).
/// Only "must be set" flags are supported (matches this codebase's usage).
fn parse_ct_state(s: &str) -> Result<(u32, u32)> {
    let mut bits = 0u32;
    for tok in s.split('+').filter(|t| !t.is_empty()) {
        bits |= match tok {
            "new" => 0x01,
            "est" => 0x02,
            "rel" => 0x04,
            "rpl" => 0x08,
            "inv" => 0x10,
            "trk" => 0x20,
            "snat" => 0x40,
            "dnat" => 0x80,
            other => bail!("unknown ct_state token '+{}' in '{}'", other, s),
        };
    }
    Ok((bits, bits))
}

/// Translate `match_fields` into a `rovs_openflow::Match`.
///
/// Two passes: first detect protocol markers (`tcp`/`udp`/`icmp`/`icmp6`/
/// `arp`/`ip`) to establish `eth_type`/`ip_proto` context, since `HashMap`
/// iteration order can't be relied on to see e.g. `udp` before `tp_dst`.
fn parse_match(fields: &HashMap<String, String>, port_map: &HashMap<String, u32>) -> Result<Match> {
    let mut m = Match::new();
    let mut ip_proto: Option<u8> = None;
    let mut eth_type: Option<u16> = None;

    if fields.contains_key("arp") {
        eth_type = Some(0x0806);
    }
    if fields.contains_key("icmp6") {
        eth_type = Some(0x86dd);
        ip_proto = Some(58);
    }
    if fields.contains_key("ip") {
        eth_type = eth_type.or(Some(0x0800));
    }
    if fields.contains_key("tcp") {
        eth_type = eth_type.or(Some(0x0800));
        ip_proto = ip_proto.or(Some(6));
    }
    if fields.contains_key("udp") {
        eth_type = eth_type.or(Some(0x0800));
        ip_proto = ip_proto.or(Some(17));
    }
    if fields.contains_key("icmp") {
        eth_type = eth_type.or(Some(0x0800));
        ip_proto = ip_proto.or(Some(1));
    }
    if let Some(et) = eth_type {
        m = m.eth_type(et);
    }
    if let Some(p) = ip_proto {
        m = m.ip_proto(p);
    }

    for (k, v) in fields {
        m = match k.as_str() {
            "arp" | "ip" | "tcp" | "udp" | "icmp" | "icmp6" => m, // handled above
            "in_port" => m.in_port(resolve_port(v, port_map)?),
            "dl_type" => {
                let et = if let Some(hex) = v.strip_prefix("0x") {
                    u16::from_str_radix(hex, 16)
                        .with_context(|| format!("invalid dl_type '{v}'"))?
                } else {
                    v.parse()
                        .with_context(|| format!("invalid dl_type '{v}'"))?
                };
                m.eth_type(et)
            }
            "dl_vlan" => m.vlan_vid(
                v.parse()
                    .with_context(|| format!("invalid dl_vlan '{v}'"))?,
            ),
            "dl_src" => m.eth_src(parse_mac(v)?),
            "tcp_flags" => {
                let mut m2 = m;
                m2.tcp_flags = Some(parse_tcp_flags(v)?);
                m2
            }
            "tp_src" => {
                let port: u16 = v.parse().with_context(|| format!("invalid tp_src '{v}'"))?;
                match ip_proto {
                    Some(6) => m.tcp_src(port),
                    Some(17) => m.udp_src(port),
                    _ => bail!("tp_src requires a 'tcp' or 'udp' marker in match_fields"),
                }
            }
            "tp_dst" => {
                let port: u16 = v.parse().with_context(|| format!("invalid tp_dst '{v}'"))?;
                match ip_proto {
                    Some(6) => m.tcp_dst(port),
                    Some(17) => m.udp_dst(port),
                    _ => bail!("tp_dst requires a 'tcp' or 'udp' marker in match_fields"),
                }
            }
            "nw_src" => {
                let (addr, prefix) = parse_cidr(v)?;
                m.ipv4_src(addr, prefix)
            }
            "nw_dst" => {
                let (addr, prefix) = parse_cidr(v)?;
                m.ipv4_dst(addr, prefix)
            }
            "ct_state" => {
                let (state, mask) = parse_ct_state(v)?;
                m.ct_state_masked(state, mask)
            }
            other => bail!(
                "unsupported OpenFlow match field '{}'={:?} — no translation available \
                 (rovs-openflow's Match type has no equivalent field)",
                other,
                v
            ),
        };
    }
    Ok(m)
}

