#!/bin/sh
set -eu
exec 2>&1

READY_DIR=/run/opdbus/runit-ready
UPSTREAM=$READY_DIR/netmk-egress-policy
READY=$READY_DIR/netmk-port-attach
DOWNSTREAM="$READY_DIR/netmk-of-restrict $READY_DIR/netmk-netclient-start"
