/// Translate a JSON-encoded `FlowEntry` into an exact, cookie-scoped
/// `DELETE_STRICT`. A delete without a cookie is rejected because a wildcard
/// cookie could remove another controller's flow with the same match.
pub fn json_flow_to_delete(flow_json: &str, port_map: &HashMap<String, u32>) -> Result<Flow> {
    let entry: JsonFlowEntry = serde_json::from_str(flow_json).context("invalid FlowEntry JSON")?;
    let cookie = entry
        .cookie
        .context("refusing OpenFlow delete without an exact cookie")?;
    let m = parse_match(&entry.match_fields, port_map)?;
    let mut flow = Flow::delete()
        .table(entry.table)
        .priority(entry.priority)
        .cookie(cookie)
        .match_fields(m);
    flow.command = FlowCommand::DeleteStrict;
    flow.cookie_mask = u64::MAX;
    Ok(flow)
}

