//! This binary never activates services. It owns only the declared netmk
//! attachment, feature policy rules/route, feature-cookie flows, and
//! authenticated adapter checks.

use anyhow::{bail, Context, Result};
use op_grpc_bridge::grpc_client::DEFAULT_NETMAKER_ADAPTER_ADDR;
use op_grpc_bridge::{GrpcClientPool, RemoteOperationClient};
use op_plugins::state_plugins::incus::IncusPlugin;
use op_plugins::state_plugins::oci::{
    GrpcAdapterConfig, OciContainerConfig, OciPlugin, PortAttachConfig,
};
use op_plugins::state_plugins::openflow::{FlowAction, FlowEntry, OpenFlowPlugin};
use std::collections::{HashMap, HashSet};
use std::process::Command;
use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH};

const COOKIE_PREFIX: u64 = 0x4e4d4b0000000000;
const COOKIE_MASK: u64 = 0xffffff0000000000;
const BRIDGE: &str = "ovsbr0";
const PORT: &str = "netmk";
const HOST_INSIDE: &str = "svc0";
const XRAY_EXISTING_ADDRESS: &str = "10.200.0.1";
const XRAY_NETMK_ADDRESS: &str = "10.200.1.2";
const FEATURE_SOURCE: &str = "10.200.1.1";

fn env_or(name: &str, default: &str) -> String {
    std::env::var(name).unwrap_or_else(|_| default.to_string())
}

fn is_already_exists(error: &anyhow::Error) -> bool {
    let text = format!("{error:#}").to_ascii_lowercase();
    text.contains("file exists") || text.contains("eexist") || text.contains("os error 17")
}

fn netmaker_attachment() -> OciContainerConfig {
    OciContainerConfig {
        name: env_or("NETMAKER_INSTANCE", "netmaker"),
        loopback_required: true,
        port_attach: Some(PortAttachConfig {
            bridge: BRIDGE.to_string(),
            port_name: PORT.to_string(),
            ip_addrs: vec![format!("{FEATURE_SOURCE}/30")],
            gateway: XRAY_NETMK_ADDRESS.to_string(),
            routes: Vec::new(),
        }),
        grpc_adapter: Some(GrpcAdapterConfig {
            binary: "op-grpc-adapters".to_string(),
            socket: "/var/lib/opdbus-runtime/netmaker/op-grpc-adapters.sock".to_string(),
            host_endpoint: DEFAULT_NETMAKER_ADAPTER_ADDR.to_string(),
        }),
        supervision: Some("runit".to_string()),
        ..OciContainerConfig::default()
    }
}

async fn attachment(command: &str) -> Result<()> {
    let plugin = OciPlugin::new();
    let desired = netmaker_attachment();
    match command {
        "reconcile" => {
            for change in plugin.reconcile_container_attachment(&desired).await? {
                println!("{change}");
            }
            if !plugin.verify_container_attachment(&desired).await? {
                bail!("netmaker attachment did not pass independent verification");
            }
        }
        "verify" => {
            if !plugin.verify_container_attachment(&desired).await? {
                bail!("netmaker attachment is not ready");
            }
        }
        "teardown" => plugin.delete_container_attachment(&desired).await?,
        other => bail!("unknown attachment action '{other}'"),
    }
    Ok(())
}

async fn discover_xray_inside(pid: u32) -> Result<String> {
    let interfaces = op_network::rtnetlink::in_network_namespace(pid, || async {
        op_network::rtnetlink::list_interfaces().await
    })
    .await?;
    interfaces
        .into_iter()
        .find(|interface| {
            interface.name != "lo"
                && interface.addresses.iter().any(|address| {
                    address.family == "inet" && address.address == XRAY_EXISTING_ADDRESS
                })
        })
        .map(|interface| interface.name)
        .with_context(|| {
            format!(
                "no xray inside interface carries required existing address {XRAY_EXISTING_ADDRESS}"
            )
        })
}

async fn host_return_route_ready() -> Result<bool> {
    let routes = op_network::rtnetlink::list_routes_for_interface(HOST_INSIDE).await?;
    Ok(routes.iter().any(|route| {
        route.get("destination").and_then(|value| value.as_str()) == Some("10.200.1.0/30")
            && route.get("gateway").and_then(|value| value.as_str()) == Some(XRAY_EXISTING_ADDRESS)
            && route.get("table").and_then(|value| value.as_u64()) == Some(254)
    }))
}

async fn egress_network_ready() -> Result<bool> {
    let xray_name = env_or("XRAY_INSTANCE", "xray");
    let pid = IncusPlugin::resolve_instance_pid(&xray_name).await?;
    let inside = discover_xray_inside(pid).await?;
    let interfaces = op_network::rtnetlink::in_network_namespace(pid, move || async move {
        op_network::rtnetlink::list_interfaces().await
    })
    .await?;
    let address_ready = interfaces.iter().any(|interface| {
        interface.name == inside
            && interface.addresses.iter().any(|address| {
                address.family == "inet"
                    && address.address == XRAY_NETMK_ADDRESS
                    && address.prefix_len == 30
            })
    });
    Ok(address_ready
        && host_return_route_ready().await?
        && op_network::rtnetlink::verify_netmk_policy_rules().await?)
}

async fn egress_network(command: &str) -> Result<()> {
    match command {
        "reconcile" => {
            let xray_name = env_or("XRAY_INSTANCE", "xray");
            let initial_pid = IncusPlugin::resolve_instance_pid(&xray_name).await?;
            let inside = discover_xray_inside(initial_pid).await?;
            if let Err(error) = op_network::rtnetlink::add_ipv4_address_in_netns(
                initial_pid,
                &inside,
                XRAY_NETMK_ADDRESS,
                30,
            )
            .await
            {
                if !is_already_exists(&error) {
                    return Err(error).context("add xray netmk gateway address");
                }
            }
            let current_pid = IncusPlugin::resolve_instance_pid(&xray_name).await?;
            if current_pid != initial_pid {
                bail!(
                    "xray restarted during reconciliation (PID {initial_pid} -> {current_pid}); retry"
                );
            }
            if !host_return_route_ready().await? {
                if let Err(error) = op_network::rtnetlink::add_ipv4_route(
                    "10.200.1.0/30",
                    Some(XRAY_EXISTING_ADDRESS),
                    HOST_INSIDE,
                    Some(254),
                )
                .await
                {
                    if !is_already_exists(&error) {
                        return Err(error).context("add feature host return route");
                    }
                }
            }
            op_network::rtnetlink::reconcile_netmk_policy_rules().await?;
            if !egress_network_ready().await? {
                bail!("native xray/host route and policy-rule verification failed");
            }
            println!("xray_inside={inside}");
            println!("xray_pid={current_pid}");
        }
        "inspect" => {
            let xray_name = env_or("XRAY_INSTANCE", "xray");
            let pid = IncusPlugin::resolve_instance_pid(&xray_name).await?;
            let inside = discover_xray_inside(pid).await?;
            println!("xray_inside={inside}");
            println!("xray_pid={pid}");
        }
        "verify" => {
            if !egress_network_ready().await? {
                bail!("native xray/host egress integration is not ready");
            }
        }
        "teardown" => {
            op_network::rtnetlink::delete_netmk_policy_rules().await?;
            op_network::rtnetlink::delete_ipv4_route(
                "10.200.1.0/30",
                Some(XRAY_EXISTING_ADDRESS),
                HOST_INSIDE,
                Some(254),
            )
            .await?;
            let xray_name = env_or("XRAY_INSTANCE", "xray");
            let pid = IncusPlugin::resolve_instance_pid(&xray_name).await?;
            let inside = discover_xray_inside(pid).await?;
            op_network::rtnetlink::del_ipv4_address_in_netns(pid, &inside, XRAY_NETMK_ADDRESS, 30)
                .await?;
        }
        other => bail!("unknown egress-network action '{other}'"),
    }
    Ok(())
}

fn parse_ports(values: &[String]) -> Result<Vec<u16>> {
    if values.is_empty() {
        bail!("at least one approved UDP destination port is required");
    }
    let mut seen = HashSet::new();
    let mut ports = Vec::new();
    for value in values {
        let port: u16 = value
            .parse()
            .with_context(|| format!("invalid UDP destination port '{value}'"))?;
        if port == 0 {
            bail!("UDP destination port must be between 1 and 65535");
        }
        if seen.insert(port) {
            ports.push(port);
        }
    }
    ports.sort_unstable();
    Ok(ports)
}

fn desired_flows(ports: &[u16]) -> Vec<FlowEntry> {
    let mut flows = vec![FlowEntry {
        table: 0,
        priority: 100,
        match_fields: HashMap::from([
            ("in_port".to_string(), PORT.to_string()),
            ("arp".to_string(), String::new()),
        ]),
        actions: vec![FlowAction::Normal],
        cookie: Some(COOKIE_PREFIX | 0x01),
        idle_timeout: 0,
        hard_timeout: 0,
    }];
    for port in ports {
        flows.push(FlowEntry {
            table: 0,
            priority: 100,
            match_fields: HashMap::from([
                ("in_port".to_string(), PORT.to_string()),
                ("udp".to_string(), String::new()),
                ("tp_dst".to_string(), port.to_string()),

                    .and_then(|v| v.as_str())
                    .filter(|s| !s.is_empty())
                    .unwrap_or(op_status);
                Err(anyhow::anyhow!("Incus operation failed: {}", err))
            }
        } else {
            let status = val
                .get("status")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_lowercase();
            if status == "success" || status == "created" || status == "accepted" {
                let metadata = val.get("metadata").cloned().unwrap_or(simd_json::json!({}));
                Ok(simd_json::to_string(&metadata)?.into_bytes())
            } else {
                let err = val
                    .get("error")
                    .and_then(|v| v.as_str())
                    .filter(|s| !s.is_empty())
                    .or_else(|| val.get("status").and_then(|v| v.as_str()))
                    .unwrap_or("Unknown Incus API error");
                Err(anyhow::anyhow!("Incus API error: {}", err))
            }
        }
    }

    /// Resolve the current init PID for a running Incus instance through the
    /// native HTTP-over-UDS API. Callers must re-resolve before namespace
    /// mutations so a restarted container cannot redirect work to a stale PID.
    pub async fn resolve_instance_pid(name: &str) -> Result<u32> {
        let body = Self::incus_api_call("GET", &format!("/1.0/instances/{}/state", name), None)
            .await
            .with_context(|| format!("query Incus state for instance '{name}'"))?;
        let mut raw = body;
        let state: simd_json::OwnedValue = simd_json::from_slice(&mut raw)
            .with_context(|| format!("parse Incus state for instance '{name}'"))?;
        let pid = state
            .get("pid")
            .and_then(|value| value.as_u64())
            .ok_or_else(|| anyhow::anyhow!("running Incus instance '{name}' has no init PID"))?;
        u32::try_from(pid).with_context(|| format!("Incus PID {pid} does not fit in u32"))
    }

    /// Fetch current instance configuration via REST API
    async fn incus_get_instance(name: &str) -> Result<simd_json::OwnedValue> {
        let body =
            Self::incus_api_call("GET", &format!("/1.0/instances/{}?recursion=1", name), None)
                .await?;
        let mut raw = body;
        simd_json::from_slice(&mut raw).context("Failed to parse Incus instance")
    }

    /// Update instance configuration via REST API (removes read-only fields first)
    async fn incus_update_instance(name: &str, mut config: simd_json::OwnedValue) -> Result<()> {
        if let Some(obj) = config.as_object_mut() {
            obj.retain(|k, _| !k.starts_with("volatile.") && !k.starts_with("image."));
        }
        let body = simd_json::to_string(&config)?;
        Self::incus_api_call("PUT", &format!("/1.0/instances/{}", name), Some(&body)).await?;
        Ok(())
    }

    /// Run an incus operation via REST API (AGENTS.md §4: no subprocess bypasses)
    async fn run_incus_command(args: &[&str]) -> Result<Vec<u8>> {
        match args {
            ["list", "--format=json"] => {
                Self::incus_api_call("GET", "/1.0/instances?recursion=1", None).await
            }
            ["init", ..] => {
                let mut image = "";
                let mut name = "";
                let mut storage_pool = None;
                let mut profiles: Vec<String> = Vec::new();
                let mut no_profiles = false;
                let mut i = 1;
                while i < args.len() {
                    match args[i] {
                        "--storage" => {
                            i += 1;
                            storage_pool = args.get(i).copied().map(String::from);
                        }
                        "--no-profiles" => {
                            no_profiles = true;
                        }
                        "--profile" => {
                            i += 1;
                            if let Some(p) = args.get(i) {
                                profiles.push(p.to_string());
                            }
                        }
                        arg if arg.starts_with('-') => {}
                        arg if image.is_empty() => image = arg,
                        arg if name.is_empty() => name = arg,
                        _ => {}
                    }
                    i += 1;
                }

                let mut body = simd_json::json!({
                    "name": name,
                    "source": { "type": "image", "alias": image },
                    "type": "container",
                });
                if no_profiles {
                    body.insert("profiles", Value::Array(Vec::new()))?;
                } else if !profiles.is_empty() {
                    let profile_values: Vec<Value> =
                        profiles.iter().map(|p| Value::from(p.as_str())).collect();
                    body.insert("profiles", Value::Array(profile_values))?;
                }
                if let Some(pool) = storage_pool {
                    body.insert(
                        "devices",
                        simd_json::json!({
                            "root": {
                                "type": "disk",
                                "pool": pool,
                                "path": "/"
                            }
                        }),
                    )?;
                }
                let body_str = simd_json::to_string(&body)?;
                Self::incus_api_call("POST", "/1.0/instances", Some(&body_str)).await
            }
            ["delete", name, "--force"] => {
                Self::incus_api_call("DELETE", &format!("/1.0/instances/{}?force=1", name), None)
                    .await
            }
            ["start", name] => {
                let body = r#"{"action":"start"}"#;
                Self::incus_api_call("PUT", &format!("/1.0/instances/{}/state", name), Some(body))
                    .await
            }
            ["stop", name] => {
                let body = r#"{"action":"stop"}"#;
                Self::incus_api_call("PUT", &format!("/1.0/instances/{}/state", name), Some(body))
                    .await
            }
            ["pause", name] => {
                let body = r#"{"action":"freeze"}"#;
                Self::incus_api_call("PUT", &format!("/1.0/instances/{}/state", name), Some(body))
                    .await
            }
            ["profile", "remove", name, profile] => {
                let mut data = Self::incus_get_instance(name).await?;
                if let Some(profiles_arr) = data.get_mut("profiles").and_then(|p| p.as_array_mut())
                {
                    profiles_arr.retain(|p| p.as_str() != Some(profile));
                }
                Self::incus_update_instance(name, data).await?;
                Ok(Vec::new())
            }
            ["profile", "add", name, profile] => {
                let mut data = Self::incus_get_instance(name).await?;
                if data.get("profiles").is_none() {
                    if let Some(obj) = data.as_object_mut() {
                        obj.insert("profiles".to_string(), simd_json::json!([]));
                    }
                }
                let profiles = data
                    .get_mut("profiles")
                    .and_then(|p| p.as_array_mut())
                    .ok_or_else(|| anyhow::anyhow!("profiles field is not an array"))?;
                if !profiles.iter().any(|p| p.as_str() == Some(profile)) {
                    profiles.push(simd_json::json!(profile));
                }
                Self::incus_update_instance(name, data).await?;
                Ok(Vec::new())
            }
            ["config", "unset", name, key] => {
                let mut data = Self::incus_get_instance(name).await?;
                if let Some(config) = data.get_mut("config").and_then(|c| c.as_object_mut()) {
                    config.remove(*key);
                }
                Self::incus_update_instance(name, data).await?;
                Ok(Vec::new())
            }
            ["config", "set", name, kv] => {
                let mut data = Self::incus_get_instance(name).await?;
                if let Some((key, value)) = kv.split_once('=') {
                    if let Some(config) = data.get_mut("config").and_then(|c| c.as_object_mut()) {
                        config.insert(key.to_string(), simd_json::json!(value));
                    } else if let Some(obj) = data.as_object_mut() {
                        let mut config = HashMap::new();
                        config.insert(key.to_string(), simd_json::json!(value));
                        obj.insert("config".to_string(), simd_json::json!(config));
                    }
                }
                Self::incus_update_instance(name, data).await?;
                Ok(Vec::new())
            }
            ["config", "device", "remove", name, device] => {
                let mut data = Self::incus_get_instance(name).await?;
                if let Some(devices) = data.get_mut("devices").and_then(|d| d.as_object_mut()) {
                    devices.remove(*device);
                }
                Self::incus_update_instance(name, data).await?;
                Ok(Vec::new())
            }
            ["config", "device", "add", name, device, dev_type, rest @ ..] => {
                let mut data = Self::incus_get_instance(name).await?;
                let mut dev_config = HashMap::new();
                dev_config.insert("type".to_string(), simd_json::json!(dev_type));
                for arg in rest.iter() {
                    if let Some((k, v)) = arg.split_once('=') {
                        dev_config.insert(k.to_string(), simd_json::json!(v));
                    }
                }
                if let Some(devices) = data.get_mut("devices").and_then(|d| d.as_object_mut()) {
                    devices.insert(device.to_string(), simd_json::json!(dev_config));
                } else if let Some(obj) = data.as_object_mut() {
                    let mut devices = HashMap::new();
                    devices.insert(device.to_string(), simd_json::json!(dev_config));
                    obj.insert("devices".to_string(), simd_json::json!(devices));
                }
                Self::incus_update_instance(name, data).await?;
                Ok(Vec::new())
            }
            _ => Err(anyhow::anyhow!("Unmapped incus CLI args: {:?}", args)),
        }
    }

