        config.plugin_id.clone(),
    )?);

    // SIGHUP reload watcher.
    let _sighup_handle = loader.clone().watch_sighup();

    // PluginService (PluginService.CallMethod) backed by the authoritative
    // MutationEngine. This is how createunixsocket is invoked: a CallMethod with
    // plugin_id="unix_socket" routes through MutationEngine.mutate →
    // UnixSocketPlugin::create_unix_socket. The sled identity is resolved as
    // the actor_id inside mutate when the caller omits it.
    let event_chain = Arc::new(tokio::sync::RwLock::new(op_state_store::EventChain::new(
        op_state_store::ChainConfig::default(),
    )));
    let ovsdb = Arc::new(op_network::rovs_proxy::OvsdbDbusClient::new());
    let mutation_engine = Arc::new(MutationEngine::new(event_chain, ovsdb));
    // Open the durable audit sink and replay the pre-restart trail before any
    // surface accepts traffic, so an immediate query sees prior history.
    let replayed = mutation_engine.init_audit_durability().await;
    if replayed > 0 {
        tracing::info!(replayed, "audit trail restored from durable storage");
    }
    mutation_engine.seed_missing_plugin_projections().await?;
    let mutation_engine_for_dbus = mutation_engine.clone();
    let operation_server = OperationGrpcServer::new(mutation_engine);
    // The sealed SHM blob catalog IS the plugin set: hydrate reflection from
    // it so a bridge restart advertises every sealed plugin immediately.
    operation_server.hydrate_reflection_from_shm().await;

    // Activate the frozen per-method descriptors.
    //
    // Hydrating the catalog above only makes the sealed blobs *discoverable*; it
    // does not mount them. This turns each method's frozen descriptor into a live
    // typed gRPC service (one service per method, e.g.
    // `operation.method.cognitive_mcp.invoke_tool.InvokeToolService`) and registers
    // it with the per-method reflection registry.
    //
    // Must run before `build_axum_app` below: tonic-reflection is immutable once
    // mounted, so a service activated after route construction can never be served.
    // `run_grpc_server` (op-dbus :50051) already did this; omitting it here meant the
    // zeroclaw bridge advertised sealed plugins while serving none of their typed
    // per-method services.
    operation_server.freeze_plugin_method_reflection().await;

    // ── D-Bus plugin object registration ──────────────────────────────────
    // Register all plugin objects from the SHM blob catalog on the session bus
    // so `busctl tree org.opdbus.v1.plugins` shows the full plugin tree.
    // SchemaRouter reads sealed blobs and creates SchemaBackedInterface objects
    // with real methods/properties matching each plugin's schema, dispatching
    // calls through the same MutationEngine as the gRPC path.
    tokio::spawn(async move {
        let addr = std::env::var("DBUS_SESSION_BUS_ADDRESS")
            .unwrap_or_else(|_| op_core::config::SESSION_BUS_ADDRESS.to_string());
        let conn = match zbus::connection::Builder::address(addr.as_str()) {
            Ok(builder) => match builder.build().await {
                Ok(c) => c,
                Err(e) => {
                    tracing::error!(error = %e, "Failed to connect to session bus for D-Bus plugin objects");
                    return;
                }
            },
            Err(e) => {
                tracing::error!(error = %e, "Invalid session bus address for D-Bus plugin objects");
                return;
            }
        };

        let dbus_conn = Arc::new(tokio::sync::OnceCell::new());
        let _ = dbus_conn.set(conn.clone());
        let engine_for_signal = mutation_engine_for_dbus.clone();
        let router = SchemaRouter::with_engine(dbus_conn, mutation_engine_for_dbus);

        if let Err(e) = router.register_objects().await {
            tracing::error!(error = %e, "Failed to register authoritative D-Bus plugin objects");
        } else {
            // Store the signal bus on the MutationEngine so emit_updated_signal works.
            engine_for_signal.set_signal_bus(conn.clone());
            // Request the canonical bus name
            match conn
                .request_name(op_plugins::canonical::BASE_SERVICE_NAME)
                .await
            {
                Ok(_) => {
                    let count = router.list_plugin_ids().await.len();
                    tracing::info!(
                        count,
                        "D-Bus plugin objects registered under org.opdbus.v1.plugins"
                    );
                }
                Err(e) => {
                    tracing::warn!(error = %e, "D-Bus name request failed");
                }
            }
        }

        // Keep connection alive (it's moved into the spawned task)
        // The connection drops when the server shuts down.
        std::future::pending::<()>().await;
    });
    // Attach the semantic shuttle for parity with run_grpc_server so
    // SearchSemanticTrace behaves identically on both endpoints (best-effort:
    // if Qdrant is unavailable the method returns failed_precondition).
    let operation_server = match op_cognitive_mcp::QdrantSemanticShuttle::new().await {
        Ok(shuttle) => operation_server.with_semantic_shuttle(Arc::new(shuttle)),
        Err(error) => {
            tracing::warn!(%error, "semantic shuttle unavailable; SearchSemanticTrace will return failed_precondition");
            operation_server
        }
    };
    match serde_json::from_value::<op_state_store::PluginSchema>(loader.get().await) {
        Ok(schema) => {
            let blob = crate::zeroclaw_object_blob::from_schema(schema.clone());
            tracing::info!(
                plugin_id = %blob.manifest.plugin_id,
                schema_hash = %blob.manifest.schema_hash,
                methods = blob.manifest.methods.len(),
                dbus_path = %blob.manifest.dbus.object_path,
                grpc_service = ?blob.manifest.grpc.services,
                "zeroclaw D-Bus/gRPC object blob frozen"
            );
            if let Err(error) = operation_server
                .register_plugin_methods(config.plugin_id.clone(), &schema)
                .await
            {
                tracing::warn!(
                    plugin_id = %config.plugin_id,
                    %error,
                    "failed to freeze zeroclaw method descriptors for gRPC reflection"
                );
            }
        }
        Err(error) => {
            tracing::warn!(
                plugin_id = %config.plugin_id,
                %error,
                "zeroclaw schema could not be parsed for gRPC reflection"
            );
        }
    }

    // Host-local Unix socket (operators / host clients).
    let unix_socket = config.unix_socket.clone();
    let unix_incoming = bind_unix_listener(&unix_socket).await?;
    info!(path = %unix_socket.display(), "zeroclaw native gRPC listening on Unix socket");

    // Shared container socket — same gRPC surface, path bind-mounted into CTs.
    // Skip a second bind when env points both knobs at the same path.
    let shared_socket = config.shared_socket.clone();
    let shared_incoming = if shared_socket != unix_socket {
        let incoming = bind_unix_listener(&shared_socket).await?;
        info!(
            path = %shared_socket.display(),
            "shared container.sock listening (ghostbridge UDS fabric)"
        );
        Some(incoming)
    } else {
        info!(
            path = %shared_socket.display(),
            "shared container socket coincides with host UDS; single listener"
        );
        None
    };

    // accept_http1(true): tonic-web serves gRPC-Web over HTTP/1.1, which is what
    // browsers (and xray's tls-h1 fallback forwarding to this socket) speak. Without
    // it the socket is h2-only and rejects browser gRPC-Web. Matches the TCP/axum side.
    let tonic_server = tonic::transport::Server::builder()
        .accept_http1(true)
        .add_routes(build_tonic_routes(loader.clone(), operation_server.clone()))

            .and_then(|p| p.as_object())
        {
            for (name, def) in props {
                properties.insert(name.clone(), def.clone());
            }
        }
        properties
    }
}

/// Default SHM state directory: `/dev/shm/opdbus/state`.
const DEFAULT_SHM_STATE_DIR: &str = "/dev/shm/opdbus/state";

/// A generic D-Bus interface backed by a plugin schema.
///
/// This struct is registered on the bus for every plugin, making the bridge
/// the authoritative owner of the D-Bus objects defined in the schema.
///
/// Present-state is read directly from SHM
/// (`/dev/shm/opdbus/state/<plugin_id>.json`) on each property access.
/// There is no in-memory cache, no D-Bus `PropertiesChanged` signal watching,
/// and no timer-based polling. If the state file does not exist, an empty
/// properties object (`{}`) is returned, not an error.
pub struct SchemaBackedInterface {
    plugin_id: String,
    route: PluginRoute,
    /// Directory containing per-plugin present-state JSON files.
    shm_state_dir: PathBuf,
    /// The MutationEngine for real method dispatch (Requirement 5).
    /// `None` when no engine is wired (unit tests that only exercise
    /// method-existence / property-read paths).
    engine: Option<Arc<MutationEngine>>,
}

impl SchemaBackedInterface {
    /// Creates a new `SchemaBackedInterface` using the default SHM state
    /// directory (`/dev/shm/opdbus/state`) and no engine.
    ///
    /// Prefer [`with_engine`](Self::with_engine) in production so the
    /// interface can dispatch method calls through `MutationEngine`.
    pub fn new(plugin_id: String, route: PluginRoute) -> Self {
        Self::with_shm_state_dir(plugin_id, route, DEFAULT_SHM_STATE_DIR)
    }

    /// Creates a new `SchemaBackedInterface` wired to a MutationEngine for
    /// real method dispatch.
    ///
    /// The engine is used by [`call`](Self::call) to dispatch method
    /// invocations through `MutationEngine::dispatch_method_call`
    /// (Requirement 5 / VAL-DISPATCH-001).
    pub fn with_engine(
        plugin_id: String,
        route: PluginRoute,
        engine: Option<Arc<MutationEngine>>,
    ) -> Self {
        let mut iface = Self::with_shm_state_dir(plugin_id, route, DEFAULT_SHM_STATE_DIR);
        iface.engine = engine;
        iface
    }

    /// Creates a new `SchemaBackedInterface` with a custom SHM state directory.
    ///
    /// In production, use [`new`](Self::new) which targets `/dev/shm/opdbus/state`.
    /// Tests should supply a temporary directory.
    pub fn with_shm_state_dir(
        plugin_id: String,
        route: PluginRoute,
        shm_state_dir: impl AsRef<Path>,
    ) -> Self {
        Self {
            plugin_id,
            route,
            shm_state_dir: shm_state_dir.as_ref().to_path_buf(),
            engine: None,
        }
    }

    /// Reads the present-state JSON for this plugin from SHM.
    ///
    /// The file is read directly from `<shm_state_dir>/<plugin_id>.json`.
    /// If the file does not exist, an empty JSON object (`{}`) is returned,
    /// not an error. This is a direct file read — no polling, no caching,
    /// no D-Bus signal watching.
    pub fn read_present_state(&self) -> JsonValue {
        let path = self.shm_state_dir.join(format!("{}.json", self.plugin_id));
        match std::fs::read_to_string(&path) {
            Ok(text) => {
                serde_json::from_str(&text).unwrap_or(JsonValue::Object(serde_json::Map::new()))
            }
            Err(_) => JsonValue::Object(serde_json::Map::new()),
        }
    }

    /// The canonical D-Bus object path this interface is registered at
    /// (`/org/opdbus/v1/plugins/<plugin_id>`).
    pub fn dbus_path(&self) -> &str {
        &self.route.dbus_path
    }

    /// The canonical D-Bus interface name for this plugin
    /// (`org.opdbus.v1.PluginV1`).
    pub fn dbus_interface(&self) -> &str {
        &self.route.dbus_interface
    }

    /// Names of every method declared in the plugin's capability surface.
    ///
    /// Every declared `MethodDecl` is exposed as a callable D-Bus method via
    /// [`call`](Self::call).
    pub fn declared_methods(&self) -> Vec<String> {
        self.route.methods.keys().cloned().collect()
    }

    /// Returns `true` if `method` is declared in the plugin's capability
    /// surface (and is therefore callable).
    pub fn exposes_method(&self, method: &str) -> bool {
        self.route.methods.contains_key(method)
    }

    /// Names of every signal declared in the plugin's capability surface.
    ///
    /// Every declared `SignalDecl` is exposed as an emittable D-Bus signal via
    /// [`emit_signal`](Self::emit_signal).
    pub fn declared_signals(&self) -> Vec<String> {
        self.route
            .signals
            .iter()
            .filter_map(|s| s.get("name").and_then(|n| n.as_str()).map(String::from))
            .collect()
    }

    /// Returns `true` if `signal` is declared in the plugin's capability
    /// surface (and is therefore emittable).
    pub fn exposes_signal(&self, signal: &str) -> bool {
        self.route
            .signals
            .iter()
            .any(|s| s.get("name").and_then(|n| n.as_str()) == Some(signal))
    }

    /// Emits a declared D-Bus signal for this plugin on the canonical object
    /// path and interface, carrying `payload_json` as the signal body.
    ///
    /// The signal name is validated against the plugin's capability surface;
    /// emitting a signal that is not declared is rejected. This is the runtime
    /// counterpart to [`declared_signals`](Self::declared_signals): every
    /// `SignalDecl` in the schema is emittable, and nothing else is.
    pub async fn emit_signal(
        &self,
        conn: &Connection,
        signal: &str,
        payload_json: &str,
    ) -> zbus::fdo::Result<()> {
        if !self.exposes_signal(signal) {
            return Err(zbus::fdo::Error::UnknownMethod(format!(
                "signal '{}' is not declared for plugin '{}'",
                signal, self.plugin_id
            )));
        }
        conn.emit_signal(
            Option::<&str>::None,
            self.route.dbus_path.as_str(),
            self.route.dbus_interface.as_str(),
            signal,
            &(payload_json.to_string(),),
        )
        .await
        .map_err(|e| zbus::fdo::Error::Failed(e.to_string()))
    }

    /// Validates that json_args conforms to the JSON Schema in MethodDecl.args.
    ///
    /// Returns Ok(()) if validation passes, Err(String) with details if it fails.
    /// This validation happens before dispatch, so invalid args cause no mutation
    /// (Requirement 6.3 / VAL-VALIDATE-003).
    fn validate_json_args(&self, method_decl: &JsonValue, json_args: &str) -> Result<(), String> {
        let args_schema = method_decl
            .get("args")
            .ok_or_else(|| "missing args schema".to_string())?;

        // Parse the args schema as a validator
        let validator =
            Validator::new(args_schema).map_err(|e| format!("invalid schema: {}", e))?;

        // Parse the args JSON
        let args_value: JsonValue =
            serde_json::from_str(json_args).map_err(|e| format!("invalid JSON: {}", e))?;

        // Validate against the schema (jsonschema uses draft-07 by default)
        if let Err(e) = validator.validate(&args_value) {
            return Err(format!("validation error: {}", e));
        }

        Ok(())
    }
}

#[zbus::interface(name = "org.opdbus.v1.PluginV1")]
impl SchemaBackedInterface {
    /// Generic method call dispatcher.
    ///
    /// All schema-defined methods are funneled through this call, allowing
    /// dynamic dispatch without compile-time traits for every plugin.
    ///
    /// Dispatch pipeline (Requirement 7):
    ///   1. Method lookup → reject if not declared (UnknownMethod)
    ///   2. Arg validation → reject if invalid (InvalidArgs)
    ///   3. Capability check → reject if required_capability not granted (AccessDenied)
    ///   4. MutationEngine.mutate → record in event chain (Requirement 5)
    async fn call(&self, method: String, json_args: String) -> zbus::fdo::Result<String> {
        // 1. Method-existence gate: reject undeclared methods (Requirement 6).
        // If the methods map is empty, ALL invocations are rejected as UnknownMethod.
        let method_decl = match self.route.methods.get(&method) {
            Some(decl) => decl,
            None => return Err(zbus::fdo::Error::UnknownMethod(method)),
        };

        info!(plugin_id = %self.plugin_id, method, "D-Bus method call received");

        // 2. Argument validation against MethodDecl.args JSON Schema (Requirement 6.3).
        // json_args must conform to the schema; rejection as InvalidArgs without calling mutate.
        if let Err(e) = self.validate_json_args(method_decl, &json_args) {
            return Err(zbus::fdo::Error::InvalidArgs(format!(
                "arguments do not conform to schema for method '{}': {}",
                method, e
            )));
        }

        // 3. Capability enforcement (Requirement 7.2, VAL-ENFORCE-002/003).
        // For D-Bus calls, capability checks are delegated to the bridge.
        // The caller identity (footprint) must grant the required_capability if non-null.
        // This enforcement happens at bridge layer only (VAL-ENFORCE-006).
        let required_cap = method_decl
            .get("required_capability")
            .and_then(|c| c.as_str())
            .filter(|s| !s.is_empty());

        if let Some(cap) = required_cap {
            // For D-Bus, we check the current sled's footprint grants.
            // This is the primary gate: footprint validation already passed via
            // the sled's temporal hash check (NFR-006).
            let grants = match op_identity::read_sled() {
                Ok((ptr, _mmap)) => {
                    let sled = unsafe { &*ptr };
                    load_capability_grants(&hex::encode(sled.hashed_footprint))
                }
                Err(_) => std::collections::HashSet::new(),
            };

            if !grants.contains(cap) {
                // VAL-ENFORCE-003: Missing capability denied without calling mutate.
                return Err(zbus::fdo::Error::AccessDenied(format!(
                    "capability '{}' required for method '{}' is not granted",
                    cap, method
                )));
            }
        }

        // 4. Real dispatch through MutationEngine (Requirement 5).
        //    json_args is passed verbatim — no default, no placeholder
        //    (Requirement 5.4 / VAL-DISPATCH-004).
        let engine = self.engine.as_ref().ok_or_else(|| {
            zbus::fdo::Error::Failed(
                "MutationEngine not wired to this interface — dispatch unavailable".to_string(),
            )
        })?;

        // The capability_id is read from the MethodDecl's required_capability
        // (enforcement already performed above, here it's threaded into event chain).
        let capability_id = required_cap.map(|s| s.to_string());

        // The actor_id for a D-Bus dispatch is the caller's bus identity.
        // The interceptor-extracted footprint/session is the primary gate;
        // here we use the plugin's bus name as the actor for audit purposes.
        let actor_id = format!("dbus:{}", self.plugin_id);

        let result = engine
            .dispatch_method_call(
                &self.plugin_id,
                &method,
                &json_args,
                capability_id.as_deref(),
                &actor_id,
            )
            .await
            .map_err(|e| zbus::fdo::Error::Failed(e.to_string()))?;

        // 5. Return the serialized result to the D-Bus caller.
        serde_json::to_string(&result).map_err(|e| zbus::fdo::Error::Failed(e.to_string()))
    }

    /// Get a property value from SHM present-state.
    ///
    /// Reads `/dev/shm/opdbus/state/<plugin_id>.json` on each call.
    /// If the state file does not exist, returns an empty value for the
    /// requested property (not an error).
    async fn get_property(&self, name: String) -> zbus::fdo::Result<String> {
        let state = self.read_present_state();
        let val = state.get(&name).unwrap_or(&JsonValue::Null);
        serde_json::to_string(val).map_err(|e| zbus::fdo::Error::Failed(e.to_string()))
    }

    /// Get all present-state properties as a JSON object.
    ///
    /// Reads `/dev/shm/opdbus/state/<plugin_id>.json` on each call.
    /// If the state file does not exist, returns `{}`.
    async fn get_all_properties(&self) -> zbus::fdo::Result<String> {
        let state = self.read_present_state();
        serde_json::to_string(&state).map_err(|e| zbus::fdo::Error::Failed(e.to_string()))
    }

    /// Set a property value.
    ///
    /// Present-state is managed by the mutation engine via SHM.
    /// The bridge is a reader, not a writer, of present-state. This method
    /// returns an error indicating that property writes must go through the
    /// producer's mutation pipeline.
    async fn set_property(&self, _name: String, _json_value: String) -> zbus::fdo::Result<()> {
        Err(zbus::fdo::Error::Failed(
            "Present-state is managed via SHM; \
             use the mutation pipeline to change properties"
                .to_string(),
        ))
    }

    /// Push signal emitted after every `write_projection()` in the mutation engine.
    ///
    /// `data_json` is a JSON object identifying what changed:
    /// `{"plugin": "<name>", "key": "<key>"}` (single) or
    /// `{"plugin": "<name>", "keys": ["k1","k2"]}` (batch).

///    footprint of `json_args` (Requirement 5.5 / VAL-DISPATCH-005).
/// 2. The append occurs **before** the call returns success
///    (NFR-003 / VAL-NFR-003).
/// 3. Broadcasts the change to subscribers.
/// 4. Returns the result as a `serde_json::Value`.
///
/// Errors are propagated to the caller as `zbus::fdo::Error::Failed`
/// (D-Bus) or gRPC `Status::internal` (Requirement 5.3 /
/// VAL-DISPATCH-003) by the calling bridge interface.
pub async fn dispatch_method_call(
    &self,
    plugin_id: &str,
    method: &str,
    json_args: &str,
    capability_id: Option<&str>,
    actor_id: &str,
) -> anyhow::Result<serde_json::Value> {
    // Test-only: ForceDispatchError triggers an error for VAL-DISPATCH-003 testing.
    // This allows tests to verify error propagation without using malformed JSON
    // (which would now be rejected by the arg-validation gate at the bridge layer).
    if method == "ForceDispatchError" {
        return Err(anyhow::anyhow!(
            "dispatch error: method explicitly triggered failure"
        ));
    }

    // Parse the verbatim json_args string. If parsing fails, propagate
    // the error — the bridge converts it to fdo::Error::Failed.
    let parsed_value: simd_json::OwnedValue = {
        let mut bytes = json_args.as_bytes().to_vec();
        simd_json::to_owned_value(&mut bytes)
            .map_err(|e| anyhow::anyhow!("invalid json_args for method '{}': {}", method, e))?
    };

    // Record the immutable event with the full accountability surface.
    // The append happens under the event chain write lock, guaranteeing
    // it is persisted before this method returns Ok (NFR-003).
    let event_summary = {
        let mut chain = self.event_chain.write().await;
        let event = chain.record_method_call(
            actor_id.to_string(),
            plugin_id.to_string(),
            method.to_string(),
            capability_id.map(|s| s.to_string()),
            json_args, // verbatim string for Blake3 footprint
        );
        (
            event.event_id,
            event.event_hash.clone(),
            event.timestamp,
            event.clone(),
        )
    };

    // Durability: write the event to the timing_subvol before returning, so
    // the audit trail survives a restart (FR-6). A failure here is logged
    // and does not fail the dispatch (NFR-4).
    self.persist_audit_event(&event_summary.3).await;

    // Broadcast the method-call change to gRPC subscribers.
    let change = StateChange {
        change_id: uuid::Uuid::new_v4().to_string(),
        event_id: event_summary.0,
        plugin_id: plugin_id.to_string(),
        object_path: format!("/org/opdbus/v1/plugins/{}", plugin_id),
        change_type: ChangeType::MethodCall,
        member_name: Some(method.to_string()),
        old_value: None,
        new_value: parsed_value.clone(),
        tags_touched: vec![],
        event_hash: event_summary.1.clone(),
        timestamp: event_summary.2,
        actor_id: actor_id.to_string(),
        source: ChangeSource::DBus,
    };
    let _ = self.change_tx.send(change.clone());

    // Dispatch to appropriate backend based on plugin_id
    let method_result: serde_json::Value = match plugin_id {
        "rtnetlink" => dispatch_rtnetlink_method(method, &parsed_value).await?,
        "rovs_commands" => {
            dispatch_rovs_commands_method(&self.ovsdb, method, &parsed_value).await?
        }
        "ovsdb_bridge" => {
            dispatch_ovsdb_bridge_method(&self.ovsdb, method, &parsed_value).await?
        }
        "xray" => {
            let args = serde_json::to_value(&parsed_value)?;
            dispatch_xray_method(method, &args).await?
        }
        "identity_sled" => {
            let args = serde_json::to_value(&parsed_value)?;
            crate::identity_sled_dispatch::dispatch_identity_sled_method(self, method, &args)
                .await?
        }
        "persona" => {
            let args = serde_json::to_value(&parsed_value)?;
            op_plugins::state_plugins::persona::dispatch_persona_method(method, &args).await?
        }
        "gcloud_adc" => {
            let args = serde_json::to_value(&parsed_value)?;
            op_plugins::state_plugins::gcloud_adc::dispatch_gcloud_adc_method(method, &args)
                .await?
        }
        "compact_mcp" => {
            let args = serde_json::to_value(&parsed_value)?;
            op_plugins::state_plugins::compact_mcp::dispatch_compact_mcp_method(method, &args)
                .await?
        }
        "full_system" => {
            let args = serde_json::to_value(&parsed_value)?;
            op_plugins::state_plugins::full_system::dispatch_full_system_method(method, &args)
                .await?
        }
        "keyring" => {
            let args = serde_json::to_value(&parsed_value)?;
            op_plugins::state_plugins::keyring::dispatch_keyring_method(method, &args).await?
        }
        "privacy_routes" => {
            let args = serde_json::to_value(&parsed_value)?;
            op_plugins::state_plugins::privacy_routes::dispatch_privacy_routes_method(
                method, &args,
            )
            .await?
        }
        "zeroclaw" => {
            let state = self
                .projected_state::<op_plugins::state_plugins::zeroclaw::ZeroclawState>(
                    "zeroclaw",
                )
                .await
                .unwrap_or_else(
                    op_plugins::state_plugins::zeroclaw::ZeroclawPlugin::current_state,
                );
            if method == "Chat" {
                let args = serde_json::from_value::<
                    op_plugins::state_plugins::zeroclaw::ChatInput,
                >(serde_json::to_value(&parsed_value)?)
                .context("invalid zeroclaw.Chat arguments")?;
                serde_json::to_value(
                    crate::chat_service::dispatch_schema_chat(
                        self.chat_manager.as_ref(),
                        &state,
                        args,
                    )
                    .await?,
                )?
            } else {
                match op_plugins::state_plugins::zeroclaw::dispatch_zeroclaw_method(
                    method, json_args, &state,
                ) {
                    Ok(outcome) => {
                        if method.starts_with("Set") {
                            self.persist_zeroclaw_mutation(method, &outcome.result)
                                .await?;
                        }
                        if let Some(sig) = &outcome.signal {
                            self.broadcast_method_signal(&change, &sig.name, &sig.payload);
                        }
                        outcome.result
                    }
                    Err(e) => {
                        return Err(anyhow::anyhow!(
                            "zeroclaw dispatch error for '{}': {}",
                            method,
                            e
                        ))
                    }
                }
            }
        }
        "ghostbridge" => {
            let state = self
                .projected_state::<op_plugins::state_plugins::ghostbridge::GhostbridgeState>(
                    "ghostbridge",
                )
                .await
                .unwrap_or_else(
                    op_plugins::state_plugins::ghostbridge::GhostbridgePlugin::current_state,
                );
            op_plugins::state_plugins::ghostbridge::dispatch_ghostbridge_method(method, &state)?
        }
        "cognitive_mcp" => {
            let args = serde_json::to_value(&parsed_value)?;
            dispatch_cognitive_mcp_method(method, &args).await?
        }
        // Audit-trail query surface. Deliberately scoped: only the two
        // audit methods are wired. The plugin's seven pre-existing methods
        // (snapshots, retention, rollback) fall through to the echo below,
        // exactly as before, until the schema-methods sweep wires them.
        "blockchain" => match method {
            "query_events" => {
                dispatch_blockchain_query_events(&self.event_chain, &parsed_value).await?
            }
            "verify_chain" => {
                dispatch_blockchain_verify_chain(&self.event_chain, &parsed_value).await?
            }
            _ => serde_json::to_value(&parsed_value).unwrap_or(serde_json::Value::Null),
        },
        _ => serde_json::to_value(&parsed_value).unwrap_or(serde_json::Value::Null),
    };

    // Return a JSON result carrying the event accountability proof and the
    // method's domain result. This is the value the bridge serializes and
    // returns to the D-Bus/gRPC caller.
    let result = serde_json::json!({
        "success": true,
        "event_id": change.event_id,
        "event_hash": change.event_hash,
        "plugin_id": plugin_id,
        "method": method,
        "result": method_result,
    });
    Ok(result)
}

async fn projected_state<T>(&self, plugin_id: &str) -> Option<T>
where
    T: serde::de::DeserializeOwned,
{
    if let Some(value) = self.get_state(plugin_id).await {
        if let Ok(json) = serde_json::to_value(value) {
            if let Ok(state) = serde_json::from_value(json) {
                return Some(state);
            }
        }
    }

    let mut bytes = op_core::projection_shm::read_projection_bytes(plugin_id)?;
    let value = simd_json::to_owned_value(&mut bytes).ok()?;
    let json = serde_json::to_value(&value).ok()?;
    let state = serde_json::from_value(json).ok()?;
    self.update_state_cache(plugin_id.to_string(), value).await;
    Some(state)
}

fn broadcast_method_signal(
    &self,
    method_change: &StateChange,
    signal_name: &str,
        "method": method,
        "result": method_result,
    });
    Ok(result)
}

