async fn dispatch_incus_method(
    method: &str,
    args: &simd_json::OwnedValue,
) -> anyhow::Result<serde_json::Value> {
    use op_plugins::state_plugins::incus::{
        AddDeviceInput, IncusPlugin, RemoveDeviceInput, RenameInstanceInput,
        RestartInstanceInput, SetInstanceConfigInput, SnapshotInstanceInput, StartInstanceInput,
        StopInstanceInput, UpdateDeviceInput,
    };

    let args = serde_json::to_value(args)?;
    match method {
        "snapshot_instance" => {
            let input: SnapshotInstanceInput = serde_json::from_value(args)?;
            IncusPlugin::create_snapshot(&input.name, &input.snapshot_name).await?;
            Ok(serde_json::json!({ "snapshot": input.snapshot_name }))
        }
        "start_instance" => {
            let input: StartInstanceInput = serde_json::from_value(args)?;
            IncusPlugin::set_instance_running(&input.name, true, false).await?;
            Ok(serde_json::json!({ "running": true }))
        }
        "stop_instance" => {
            let input: StopInstanceInput = serde_json::from_value(args)?;
            IncusPlugin::set_instance_running(
                &input.name,
                false,
                input.force.unwrap_or(false),
            )
            .await?;
            Ok(serde_json::json!({ "running": false }))
        }
        "restart_instance" => {
            let input: RestartInstanceInput = serde_json::from_value(args)?;
            IncusPlugin::set_instance_running(
                &input.name,
                false,
                input.force.unwrap_or(false),
            )
            .await?;
            IncusPlugin::set_instance_running(&input.name, true, false).await?;
            Ok(serde_json::json!({ "running": true }))
        }
        "rename_instance" => {
            let input: RenameInstanceInput = serde_json::from_value(args)?;
            IncusPlugin::rename_instance(&input.name, &input.new_name).await?;
            Ok(serde_json::json!({ "name": input.new_name }))
        }
        "set_instance_config" => {
            let input: SetInstanceConfigInput = serde_json::from_value(args)?;
            IncusPlugin::set_instance_config(
                &input.name,
                &input.key,
                input.value.as_deref(),
            )
            .await?;
            Ok(serde_json::json!({ "key": input.key, "set": input.value.is_some() }))
        }
        "add_device" => {
            let input: AddDeviceInput = serde_json::from_value(args)?;
            let changes = IncusPlugin::reconcile_device(
                &input.instance_name,
                &input.device_name,
                &input.device,
            )
            .await?;
            Ok(serde_json::json!({ "changes": changes }))
        }
        "update_device" => {
            let input: UpdateDeviceInput = serde_json::from_value(args)?;
            let changes = IncusPlugin::reconcile_device(
                &input.instance_name,
                &input.device_name,
                &input.device,
            )
            .await?;
            Ok(serde_json::json!({ "changes": changes }))
        }
        "remove_device" => {
            let input: RemoveDeviceInput = serde_json::from_value(args)?;
            let changes =
                IncusPlugin::remove_device(&input.instance_name, &input.device_name).await?;
            Ok(serde_json::json!({ "changes": changes }))
        }
        other => anyhow::bail!("Incus method '{other}' has no native runtime dispatcher"),
    }
}

