pub async fn dispatch_netmaker_method(method: &str, args: &JsonValue) -> Result<JsonValue> {
    let plugin = NetmakerPlugin::new(NetmakerConfig::default());
    match method {
        "join_network" => {
            let input: JoinNetworkInput = serde_json::from_value(args.clone())
                .context("invalid join_network arguments")?;
            plugin
                .join_network(&input.network, input.token.as_deref().unwrap_or(""))
                .await?;
            Ok(serde_json::to_value(
                super::plugin_scaffold_helpers::AckOutput { success: true },
            )?)
        }
        "leave_network" => {
            let input: LeaveNetworkInput = serde_json::from_value(args.clone())
                .context("invalid leave_network arguments")?;
            plugin.leave_network(&input.network).await?;
            Ok(serde_json::to_value(
                super::plugin_scaffold_helpers::AckOutput { success: true },
            )?)
        }
        "list_networks" => {
            let _input: ListNetworksInput = serde_json::from_value(args.clone())
                .context("invalid list_networks arguments")?;
            NetmakerPlugin::list_networks_api().await
        }
        "list_nodes" => {
            let input: ListNodesInput = serde_json::from_value(args.clone())
                .context("invalid list_nodes arguments")?;
            NetmakerPlugin::list_nodes_api(&input.network).await
        }
        "get_node" => {
            let input: GetNodeInput = serde_json::from_value(args.clone())
                .context("invalid get_node arguments")?;
            NetmakerPlugin::get_node_api(&input.network, &input.node_id).await
        }
        "update_node" => {
            let input: UpdateNodeInput = serde_json::from_value(args.clone())
                .context("invalid update_node arguments")?;
            NetmakerPlugin::update_node_api(&input.network, &input.node_id, &input.payload).await
        }
        _ => anyhow::bail!("unknown netmaker method: {method}"),
    }
}

