/// POST /api/v1/egress — create an egress resource. Netmaker requires the
/// `nat_type` discriminator (`direct_nat`/`virtual_nat`); a boolean `nat`
/// field is rejected with HTTP 400.
async fn create_egress_api(input: &CreateEgressInput) -> Result<JsonValue> {
    let master_key = Self::netmaker_master_key()?;
    let mut body = serde_json::json!({
        "name": input.name,
        "network": input.network,
        "range": input.range,
        "nat_type": input.nat_type,
    });
    if let Some(desc) = input.description.as_deref() {
        body["description"] = serde_json::json!(desc);
    }
    let resp = reqwest::Client::new()
        .post(format!("{}/api/v1/egress", Self::netmaker_api_base()))
        .bearer_auth(master_key)
        .json(&body)
        .send()
        .await
        .context("Netmaker API request failed (POST /api/v1/egress)")?;
    if !resp.status().is_success() {
        anyhow::bail!(
            "Netmaker API returned {}: POST /api/v1/egress",
            resp.status()
        );
    }
    resp.json()
        .await
        .context("Netmaker API returned invalid JSON (POST /api/v1/egress)")
}

/// DELETE /api/v1/egress/:id — remove an egress resource.
async fn delete_egress_api(egress_id: &str) -> Result<()> {
    let master_key = Self::netmaker_master_key()?;
    let resp = reqwest::Client::new()
        .delete(format!(
            "{}/api/v1/egress/{egress_id}",
            Self::netmaker_api_base()
        ))
        .bearer_auth(master_key)
        .send()
        .await
        .context("Netmaker API request failed (DELETE /api/v1/egress/:id)")?;
    if !resp.status().is_success() {
        anyhow::bail!(
            "Netmaker API returned {}: DELETE /api/v1/egress/{egress_id}",
            resp.status()
        );
    }
    Ok(())
}

