    if fields.is_empty() {
        proto.push_str("  // Empty schema object.\n");
    }

    for field in fields {
        let repeated = if field.repeated { "repeated " } else { "" };
        proto.push_str(&format!(
            "  {}{} {} = {};\n",
            repeated, field.proto_type, field.name, field.number
